  return <DashboardContext.Provider value={context}><AsideHeader className=\"app-shell\" compact={compact} onChangeCompact={setCompact} hideCollapseButton hideSectionDividers logo={{text:()=> <span className=\"brand-name\">orbit<span className=\"brand-dot\">.</span></span>,icon:LayoutCellsLarge,onClick:()=>setTab('overview')}} aboveMenuContent={<><div className=\"workspace-picker\">{"'!compact ? <DropdownMenu renderSwitcher={props=><Button {...props} view="outlined" size="xl" width="max"><span className="workspace-avatar">С</span><span className="workspace-label">{workspace}<small>Рабочее пространство</small></span><Icon data={ChevronDown} size={14}/></Button>} items={['"'Студия Дизайн','Личное пространство'].map(name=>({text:name,action:()=>{setWorkspace(name);setToast("'`Выбрано: ${name}`);}}))}/> : <Button view="flat" onClick={()=>setCompact(false)} aria-label="Развернуть меню"><span className="workspace-avatar">С</span></Button>}</div>{!compact&&<div className="nav-caption">РАБОЧЕЕ ПРОСТРАНСТВО</div>}</>} menuItems={navItems.map(item=>({...item,current:tab===item.id,onItemClick:()=>setTab(item.id),className:'"'navigation-item'}))} renderFooter={()=> <div className=\"sidebar-footer\">{"'!compact&&<div className="plan-card"><span className="plan-icon">✧</span><b>Больше возможностей</b><p>Все данные. Больше виджетов.<br/>Никаких ограничений.</p><Button view="outlined" size="l" width="max" onClick={()=>setDialog('"'plan')}>Открыть Pro<Icon data={ArrowUpRight} size={15}/></Button></div>}<Button className=\"sidebar-link\" view=\"flat\" width=\"max\" onClick={()=>setDialog('settings')}><Icon data={Gear} size={18}/>{"'!compact&&'"'Настройки'}</Button><Button className=\"sidebar-link\" view=\"flat\" width=\"max\" onClick={()=>setDialog('help')}><Icon data={CircleQuestion} size={18}/>{"'!compact&&'"'Помощь и поддержка'}</Button>{"'!compact&&<div className="sidebar-signature"><span className="live-dot"/>Все системы работают<span>↗</span></div>}</div>} renderContent={()=> <div className="page"><header className="topbar"><div className="breadcrumbs"><Button view="flat" size="s" onClick={()=>setCompact(!compact)} aria-label="Свернуть или развернуть меню"><Icon data={LayoutCellsLarge} size={16}/></Button><span className="breadcrumb-divider"/><span>Рабочее пространство</span><Icon data={ChevronRight} size={12}/><b>{navItems.find(n=>n.id===tab)?.title}</b></div><div className="topbar-right"><span className="demo-tag">Демо-данные</span><Button className="notification-button" view="flat" onClick={()=>setDialog('"'notifications')} aria-label=\"Уведомления\"><Icon data={Bell} size={18}/><i/></Button><span className=\"topbar-divider\"/><DropdownMenu renderSwitcher={props=><Button {...props} view=\"flat\" size=\"l\" aria-label=\"Профиль\"><span className=\"profile-avatar\">АК</span><Icon data={ChevronDown} size={12}/></Button>} items={[{text:'Алексей Козлов · Владелец',action:()=>setDialog('profile')},{text:'Настройки профиля',action:()=>setDialog('settings')} ]}/></div></header><main className=\"main-content\"><div className=\"page-heading\"><div><div className=\"eyebrow\">ВАШ БИЗНЕС В ОДНОМ МЕСТЕ</div><Text variant=\"display-2\" className=\"page-title\">{tab==='overview'?'Обзор бизнеса':navItems.find(n=>n.id===tab)?.title}</Text><p>Всё важное — на вашем дашборде. Настройте его под себя.</p></div><Button view=\"outlined\" size=\"l\" onClick={exportReport}><Icon data={ArrowDownToLine} size={16}/>Экспорт</Button></div><div className=\"dashboard-tabs\"><div className=\"dashboard-tab\"><span className=\"tab-symbol\"><Icon data={LayoutCellsLarge} size={15}/></span>Основной дашборд<span className=\"tab-count\">{config.items.length}</span></div><Button view=\"flat-secondary\" size=\"s\" onClick={()=>setDialog('new-dashboard')} aria-label=\"Создать дашборд\"><Icon data={Plus} size={16}/></Button><span className=\"saved-status\"><Icon data={CircleCheck} size={13}/>{saved?'Все изменения сохранены':'Не удалось сохранить'}</span></div><div className=\"dashboard-toolbar\"><div className=\"toolbar-left\"><Select className=\"period-select\" value={[period]} onUpdate={v=>setPeriod(v[0])} options={[{value:'7',content:'Последние 7 дней'},{value:'30',content:'Последние 30 дней'},{value:'90',content:'Последние 90 дней'}]} size=\"m\"/><span className=\"date-caption\"><Icon data={Calendar} size={14}/>{period==='7'?'25–31 окт. 2024':period==='90'?'3 авг. – 31 окт. 2024':'1 окт. – 31 окт. 2024'}</span></div><div className=\"toolbar-right\"><Button view={edit?'outlined-action':'outlined'} selected={edit} size=\"m\" onClick={()=>{setEdit("'!edit);if(edit)setToast('"'Расположение виджетов сохранено');}}><Icon data={edit?CircleCheck:Sliders} size={15}/>{edit?'Готово':'Настроить'}</Button><Button view=\"action\" size=\"m\" onClick={()=>{setQuery('');setCatalog(true);}}><Icon data={Plus} size={16}/>Добавить виджет</Button></div></div>{edit&&<div className=\"edit-notice\"><Icon data={Grip} size={16}/><span>Перетаскивайте виджеты за заголовок и меняйте размер за нижний угол.</span><Button view=\"flat\" size=\"s\" onClick={()=>{setConfig(initialConfig);setToast('Начальное расположение восстановлено');}}><Icon data={ArrowRotateLeft} size={14}/>Сбросить</Button></div>}<div className=\"dashboard-grid\">{config.items.length ? <DashKit key={narrow?'mobile':'desktop'} config={narrow?mobileConfig:config} editMode={edit&&"'!narrow} noOverlay draggableHandleClassName="widget-drag-handle" onChange={({config:next})=>{if(!narrow)setConfig(next);}}/> : <div className="empty-state"><Icon data={LayoutCellsLarge} size={36}/><Text variant="header-1">Ваш дашборд — чистый лист</Text><p>Добавьте первый виджет, чтобы увидеть свои показатели.</p><Button view="action" onClick={()=>setCatalog(true)}>Добавить виджет</Button></div>}</div><footer className="page-footer"><span><span className="live-dot"/>Обновлено только что <span className="footer-separator">·</span> Данные обновляются каждые 5 минут</span><span>Сделано для ясности<span className="footer-orbit">orbit.</span></span></footer></main></div>}/>
  <Modal open={catalog} onOpenChange={setCatalog} contentClassName="catalog-modal"><div className="modal-heading"><div><Text variant="header-1">Добавить виджет</Text><p>Соберите дашборд, который работает на вас.</p></div><Button view="flat" onClick={()=>setCatalog(false)} aria-label="Закрыть"><Icon data={Xmark} size={18}/></Button></div><TextInput size="l" value={query} onUpdate={setQuery} placeholder="Найти виджет" startContent={<Icon data={Magnifier} size={17}/>} hasClear/><div className="catalog-tabs">{['"'Все','Показатели','Графики','Таблицы','Другое'].map(cat=><Button key={cat} size=\"s\" view={cat===category?'flat-action':'flat'} selected={cat===category} onClick={()=>setCategory(cat)}>{cat}</Button>)}</div><div className=\"catalog-list\">{widgetCatalog.filter(w=>(category==='Все'||category===w.category)&&"'`${w.title} ${w.description}`.toLowerCase().includes(query.toLowerCase())).map(w=><div className="catalog-item" key={w.kind}><span className="catalog-icon"><Icon data={w.icon} size={22}/></span><div><Text variant="subheader-2">{w.title}</Text><p>{w.description}</p></div><Button view="outlined" onClick={()=>addWidget(w.kind)} aria-label={`Добавить ${w.title}`}><Icon data={Plus} size={16}/></Button></div>)}{!widgetCatalog.some(w=>(category==='"'Все'||category===w.category)&&"'`${w.title} ${w.description}`.toLowerCase().includes(query.toLowerCase()))&&<div className="search-empty">Виджеты не найдены. Попробуйте другой запрос.</div>}</div></Modal>
