function CreateDashboard({onCreate}:{onCreate:(name:string)=>void}) {const[name,setName]=useState('Мой дашборд');return <form className=\"dialog-body\" onSubmit={e=>{e.preventDefault();if(name.trim())onCreate(name.trim());}}><TextInput label=\"Название\" value={name} onUpdate={setName} size=\"l\"/><p>Откроется пустой дашборд. Текущий набор виджетов будет заменён.</p><Button type=\"submit\" view=\"action\" disabled={"'!name.trim()}>Создать дашборд</Button></form>;}
