  const exportReport = () => {const csv='\\uFEFFПоказатель;Значение\\nВыручка;1284560\\nЗаказы;1842\\nПосетители;24839\\nКонверсия;3.84\\n';const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='orbit-report.csv';a.click();URL.revokeObjectURL(url);setToast('Отчёт скачан');};
